function ProductCard({ p, addToCart }) {
  return (
    <div style={{
      width: 220,
      borderRadius: 10,
      overflow: "hidden",
      boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
      background: "#fff",
      transition: "0.3s"
    }}>
      <img
        src={p.image}
        style={{ width: "100%", height: 180, objectFit: "cover" }}
      />

      <div style={{ padding: 10 }}>
        <h4>{p.name}</h4>

        <p style={{
          color: "red",
          fontWeight: "bold"
        }}>
          {Number(p.price).toLocaleString()} VND
        </p>

        <button
          onClick={() => addToCart(p)}
          style={{
            width: "100%",
            padding: 10,
            background: "#ffd400",
            border: "none",
            cursor: "pointer",
            borderRadius: 5
          }}
        >
          🛒 Thêm vào giỏ
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
